      "19-21절 갓과 아셀과 납달리는 각각 대적을 추격하는 용맹무쌍함, 왕의 진수를 공급할 만큼 비옥하고 풍요로움, 암사슴처럼 아름답고 기민함을 그 축복으로 받습니다. 이들 역시 주목을 받지 못하지만 먼저 된 자처럼 복을 누리게 될 것입니다. 22-26절 요셉은 유다와 더불어 가장 큰 복을 받는데, 이 두 지파가 남유다와 북이스라엘의 중심이 될 것을 내다보게 합니다. 요셉 지파는 담을 넘는 무성한 가지처럼 번성하며, 전능하신 하나님 이스라엘의 반석이시요 목자이신 하나님이 함께하심으로 강한 나라가 될 것입니다. 그들은 장자의 복을 받아 풍부한 수자원과 사람과 짐승의 풍요로운 출산을 누릴 것이며, 그가 받는 복은 태고적 산맥과 영원한 언덕이 받는 풍성함보다 클 것입니다(26절: 참조, 새번역). 하지만 북이스라엘의 멸망이 보여주듯이 그들이 하나님을 떠났을 때는 모두 잃게 될 것입니다. 이 복은 기계적이거나 운명적인 것이 아니며, 하나님이 주신 복에 늘 합당하게 반응할 때 온전히 누릴 수 있음을 깨닫습니다.",
      "27절 베냐민은 매우 호전적인 강력한 지파가 될 것입니다. 훗날 전사들을 많이 배출하고, 중부 가나안 정복 전쟁을 주도하며, 초대 왕 사울을 배출합니다.",
      "28절 야곱은 자의적으로 축복하지 않고, 하나님이 정해주신 각 사람의 분량대로 축복했습니다. 그들은 받은 복에 대해서 받은 만큼 하나님 나라를 위해 책임 있게 반응해야 할 것입니다. 나도 성령께서 뜻대로 주신 은사를 다른 지체와 비교하지 않고, 오직 그리스도의 몸을 세우기 위해 순종하고 있습니까?"
